import { useEffect, useMemo, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { bscJson } from "@/shared/lib/core/bsc";
import { usePageTabs } from "@/shared/hooks/usePageTabs";
import { Screen } from "@/shared/ui/layouts/Screen";

export interface DataEntity {
  id: string;
  name: string;
  summary?: string;
  shape?: string;
  fields?: string[];
  /** `single` = exactly one live instance app-wide; absent means `many`. */
  instances?: "single" | "many";
  src?: string;
  provides?: string;
}
export async function loadEntities(): Promise<DataEntity[]> {
  return bscJson<DataEntity[]>(null, ["data", "entity", "list"], []);
}

/**
 * The LANGUAGE an entity lives in — the Data graph's axis
 * (`define-the-axis-for-teams-data-and-sounds`).
 *
 * Derived from `src`, not stored, because it is already implied by where the entity is defined and a
 * second stored copy would be one more thing to keep true. `.rs` is Rust; `.ts`/`.tsx` are TypeScript;
 * anything else (or a missing `src`) is `other`, so an entity is never dropped for want of a suffix.
 *
 * THE AXIS IS A LENS, NOT A PARTITION (`the-tab-is-a-lens-not-a-partition`), and here that is not
 * hypothetical: `store-plan` is a TypeScript view of the SAME data plan.db holds in Rust. Those are two
 * ends of one boundary, so the tab must scope which entities are listed and never claim the two sides
 * are unrelated.
 */
export function entityLang(e: DataEntity): string {
  const src = (e.src ?? "").toLowerCase();
  if (src.endsWith(".rs")) return "rust";
  if (src.endsWith(".ts") || src.endsWith(".tsx")) return "typescript";
  return "other";
}

/** Display label for a language id. */
const LANG_LABEL: Record<string, string> = { typescript: "TypeScript", rust: "Rust", other: "Other" };
/** Canonical order; a language not listed sorts after, and `other` always last. */
const LANG_ORDER = ["typescript", "rust"];
export function DataGraphPage() {
  const [entities, setEntities] = useState<DataEntity[] | null>(null);

  useEffect(() => {
    let alive = true;
    void loadEntities().then((e) => {
      if (alive) setEntities(e);
    });
    return () => {
      alive = false;
    };
  }, []);

  // One tab per language the graph ACTUALLY holds — the same rule the Algorithms tabs use. A language
  // with no entities gets no tab rather than a dead one; today that means TypeScript alone, because
  // every entity is a frontend store and the Rust-side stores (plan.db, skills.db, the DuckDB model)
  // are simply not in the graph yet. That gap is real and worth fixing, but an empty tab is a worse way
  // to say so than not offering one.
  const langs = useMemo(() => {
    const present = [...new Set((entities ?? []).map(entityLang))];
    const known = LANG_ORDER.filter((l) => present.includes(l));
    const extra = present.filter((l) => !known.includes(l) && l !== "other").sort();
    return [...known, ...extra, ...(present.includes("other") ? ["other"] : [])];
  }, [entities]);
  const langTabs = useMemo(
    () => langs.map((l) => ({ id: l, label: LANG_LABEL[l] ?? l, hint: `${LANG_LABEL[l] ?? l} entities` })),
    [langs],
  );
  // UNCONTROLLED (`navigation-vocabulary-follows-the-new-page-structure`) — the active language lives
  // at `activePageTab["data"]`, so `bsc navigate page rust` reaches it. A persisted language the graph
  // no longer holds heals to the first tab, which matters here more than elsewhere: the set of
  // languages is derived from the entities and genuinely changes as the graph grows.
  const { tabs, activeId, select, reorder } = usePageTabs("data", langTabs);
  const shown = (entities ?? []).filter((e) => entityLang(e) === activeId);

  if (entities && entities.length === 0) {
    return (
      <EmptyState
        title="No entities yet"
        description="The data graph is the global store of our own data model — add one with `bsc data entity set`."
      />
    );
  }

  return (
    <Screen
      className="data-workspace"
      tabs={tabs}
      active={activeId}
      onSelect={select}
      onReorder={reorder}
    >
    <Box style={{ flex: 1, minHeight: 0, overflow: "auto", padding: 16 }}>
      <Stack gap={12}>
        <Stack gap={2}>
          <Text weight={600} size={15}>Data</Text>
          <Text size={12} tone="muted">
            The global data graph — our own entities, connected to components by shape and to algorithms
            by what they read and write.
          </Text>
        </Stack>

        {shown.map((e) => (
          <Box
            key={e.id}
            style={{
              border: "1px solid var(--border)",
              borderRadius: 8,
              padding: 12,
              background: "var(--bg-elev)",
            }}
          >
            <Stack gap={6}>
              <Row gap={8} align="center" style={{ minWidth: 0, flexWrap: "wrap" }}>
                <Text weight={600} size={13}>{e.name}</Text>
                <Text as="code" mono size={11} tone="dim">{e.id}</Text>
                {/* The fact no other pillar could state: there is exactly ONE of this at runtime. */}
                {e.instances === "single" && (
                  <Text as="code" mono size={10} tone="accent" style={{ textTransform: "uppercase" }}>
                    single instance
                  </Text>
                )}
                {e.shape && (
                  <Text as="code" mono size={10} tone="muted">shape: {e.shape}</Text>
                )}
              </Row>

              {e.summary && <Text size={12} tone="muted">{e.summary}</Text>}

              {!!e.fields?.length && (
                <Row gap={6} align="center" style={{ minWidth: 0, flexWrap: "wrap" }}>
                  <Eyebrow size={10}>Fields</Eyebrow>
                  {e.fields.slice(0, 12).map((f) => (
                    <Text key={f} as="code" mono size={11}>{f}</Text>
                  ))}
                  {e.fields.length > 12 && (
                    <Text size={11} tone="dim">+{e.fields.length - 12} more</Text>
                  )}
                </Row>
              )}

              {e.provides && (
                <Text as="code" mono size={11} tone="dim">{e.provides}</Text>
              )}
            </Stack>
          </Box>
        ))}
      </Stack>
    </Box>
    </Screen>
  );
}

